bash -lc 'python - << "PY"
import sys
p = "/src/php-src/main/spprintf.c"
with open(p, "r", encoding="utf-8") as f:
    s = f.read()
old = """case 's':
		s = va_arg(ap, char *);
		if (s != NULL) {
			if (!adjust_precision) {
				s_len = strlen(s);
			} else {
				s_len = zend_strnlen(s, precision);
			}
		} else {
			s = S_NULL;
			s_len = S_NULL_LEN;
		}
		pad_char = ' ';
		break;"""
new = """case 's':
		s = va_arg(ap, char *);
		if (s != NULL) {
			size_t max_len = precision ? (size_t)precision : 4096;
			s_len = zend_strnlen(s, max_len);
		} else {
			s = S_NULL;
			s_len = S_NULL_LEN;
		}
		pad_char = ' ';
		break;"""
if old in s:
    s2 = s.replace(old, new)
    with open(p, 'w', encoding='utf-8') as f:
        f.write(s2)
    print('Patched spprintf.c')
else:
    print('Patch fragment not found; patch skipped')
PY'
